struct timeval { long tv_sec, tv_usec; };

struct itimerval {
    struct timeval it_interval; // Periodic interval
    struct timeval it_value;    // Initial value
};

// Set ITIMER_REAL (wall clock) for 1 second initial expiration
const int WHICH = ITIMER_REAL;

struct itimerval new_timer = {
    .it_interval = {0, 0},   // Non-periodic
    .it_value = {1, 0}       // 1 second initial delay
};

struct itimerval old_timer;

// Set timer; retrieves previous settings into &old_timer
setitimer(WHICH, &new_timer, &old_timer);
